HERO_STR_STATIC(hero_str_336c215a, "`int` is not a word in this language \342\200\224 an integer says its width: `i64`, and also `i8` `i16` `i32` `u8` `u16` `u32` `u64`");
HERO_STR_STATIC(hero_str_1b9a87, "i64");
HERO_STR_STATIC(hero_str_526d2a67, "`struct` is not a word in this language \342\200\224 use `record`: `record Point`");
HERO_STR_STATIC(hero_str_a9d8e2e, "`enum` is not a word in this language \342\200\224 use `variant`: `variant Token`");
HERO_STR_STATIC(hero_str_678c6d51, "`union` is not a word in this language \342\200\224 use `variant`: `variant Token`");
HERO_STR_STATIC(hero_str_14008e6b, "`class` is not a word in this language \342\200\224 use `record` (there is no inheritance)");
HERO_STR_STATIC(hero_str_403a9619, "`fn` is not a word in this language \342\200\224 use `function`: `function f(x: i64) -> i64`");
HERO_STR_STATIC(hero_str_18600033, "`func` is not a word in this language \342\200\224 use `function`");
HERO_STR_STATIC(hero_str_40117f8c, "`def` is not a word in this language \342\200\224 use `function`");
HERO_STR_STATIC(hero_str_4a851d0c, "`let` is not a word in this language \342\200\224 bind with `=`: `x = 5`");
HERO_STR_STATIC(hero_str_78d1c254, "`var` is not a word in this language \342\200\224 declare a mutable with `@`: `v: i64 @ 0`");
HERO_STR_STATIC(hero_str_609b34a2, "`const` is not a word in this language \342\200\224 use `constant`: `constant MAX: i64`");
HERO_STR_STATIC(hero_str_4b3aa2d3, "`elif` is not a word in this language \342\200\224 write `else if`");
HERO_STR_STATIC(hero_str_5685150e, "else if");
HERO_STR_STATIC(hero_str_2f103261, "`switch` is not a word in this language \342\200\224 use `match`");
HERO_STR_STATIC(hero_str_6498bd33, "`case` is not a word in this language \342\200\224 a `match` arm is `.name => expr`");
HERO_STR_STATIC(hero_str_7220fe5a, "there is no null in this language \342\200\224 absence is a fallible type: `i64?`, and a C pointer's zero is `nullptr`");
HERO_STR_STATIC(hero_str_13ddc99e, "there are no exceptions in this language \342\200\224 errors are values: `fail(code, msg)`, propagate with `?`");
HERO_STR_STATIC(hero_str_7a7b3cb6, "`import` and `include` are not words in this language \342\200\224 a module is named with `use`: `use geom`");
HERO_STR_STATIC(hero_str_eb4a791, "main");
HERO_STR_STATIC(hero_str_44b3ecc, "base_prefix_case");
HERO_STR_STATIC(hero_str_7af7cf, "` writes the base in uppercase \342\200\224 this language spells it `");
HERO_STR_STATIC(hero_str_31615438, "there is exactly one way to write any program (\302\2474.15). The ");
HERO_STR_STATIC(hero_str_f9fe62, " digits themselves may be either case, so `");
HERO_STR_STATIC(hero_str_7af7f094, "` is the same value written correctly");
HERO_STR_STATIC(hero_str_773a3767, "write the prefix as `");
HERO_STR_STATIC(hero_str_5291e62, "` starts with a zero, and this language reads no meaning into that");
HERO_STR_STATIC(hero_str_6ab721bc, "C, and every language that copied it, reads a leading zero as octal \342\200\224 so `");
HERO_STR_STATIC(hero_str_2f379b40, "` is a number a reader will size wrong. Write `0o");
HERO_STR_STATIC(hero_str_32e98c03, "` for the octal value, or `");
HERO_STR_STATIC(hero_str_2826d000, "` for the decimal one");
HERO_STR_STATIC(hero_str_6410ce09, "octal: `0o");
HERO_STR_STATIC(hero_str_18ff, "0o");
HERO_STR_STATIC(hero_str_5db6cbf8, "decimal: `");
HERO_STR_STATIC(hero_str_10f0a177, "exponent_literal");
HERO_STR_STATIC(hero_str_3a4988c0, "` is not a number in this language \342\200\224 there are no exponents. Write the digits out, or compute it: `");
HERO_STR_STATIC(hero_str_43045550, " * pow(base: 10.0, exponent: \342\200\246)` through the FFI (\302\2474.19)");
HERO_STR_STATIC(hero_str_7113f98d, "empty_base_literal");
HERO_STR_STATIC(hero_str_187f4884, "` names a base and then stops \342\200\224 a number needs digits");
HERO_STR_STATIC(hero_str_1344a00, " literal is written `");
HERO_STR_STATIC(hero_str_6656287b, "` followed by ");
HERO_STR_STATIC(hero_str_7cc04880, "misplaced_separator");
HERO_STR_STATIC(hero_str_6a802674, "`_` groups digits, so it goes between two of them");
HERO_STR_STATIC(hero_str_78a9cbe1, "`1_000_000` and `0xff_ff` are the shape; a separator that leads, trails or doubles is a typo rather than a grouping");
HERO_STR_STATIC(hero_str_3c95239a, "digit_not_in_base");
HERO_STR_STATIC(hero_str_152632d4, "` is not ");
HERO_STR_STATIC(hero_str_5a11abb1, " digit");
HERO_STR_STATIC(hero_str_6a212e8f, " literal admits ");
