HERO_STR_STATIC(hero_str_1181cf32, "` in `");
HERO_STR_STATIC(hero_str_72063df6, "` \342\200\224 clang read the header and the types disagree");
HERO_STR_STATIC(hero_str_339821de, "an `extern constant` takes its value from the header (\302\2474.19), so its type is the header's too: correct the declared type, or name the header that spells `");
HERO_STR_STATIC(hero_str_1070b187, "` as `");
HERO_STR_STATIC(hero_str_32f20594, "` does not return `");
HERO_STR_STATIC(hero_str_48cc5ea1, "` \342\200\224 that is what `");
HERO_STR_STATIC(hero_str_7fb4af4b, "` says, and clang read it");
HERO_STR_STATIC(hero_str_3bdd0bd2, "an `extern` is checked against the real header (\302\2474.19): correct the result type, or name the header that declares this `");
HERO_STR_STATIC(hero_str_3d643630, "not a constancy assertion");
HERO_STR_STATIC(hero_str_31d5203c, "the marker's tail is empty");
HERO_STR_STATIC(hero_str_11905d6e, "ffi_not_constant");
HERO_STR_STATIC(hero_str_6236fb02, "` has `");
HERO_STR_STATIC(hero_str_21a446e3, "`, but not as a constant \342\200\224 clang cannot read its value while compiling");
HERO_STR_STATIC(hero_str_5a8370f8, "a `constant` names one value forever (\302\2474.4), and `");
HERO_STR_STATIC(hero_str_6244093a, "` is an object or a macro that expands to one \342\200\224 reading it twice could give two answers, which is the mutable global \302\2474.2 forbids. A C object is reached through an `extern function` that returns it");
HERO_STR_STATIC(hero_str_7f5b0549, "call to undeclared function '");
HERO_STR_STATIC(hero_str_74692024, "call to undeclared library function '");
HERO_STR_STATIC(hero_str_76b3a9fb, "use of undeclared identifier '");
HERO_STR_STATIC(hero_str_61f6e6aa, "not an undeclared-name line");
HERO_STR_STATIC(hero_str_313ef0e4, "must use 'struct' tag to refer to type '");
HERO_STR_STATIC(hero_str_3da6e00e, "the tag class owns this name");
HERO_STR_STATIC(hero_str_56a08d2, "ffi_unknown_name");
HERO_STR_STATIC(hero_str_13a84ace, "` declares no `");
HERO_STR_STATIC(hero_str_4e380f0a, "` \342\200\224 clang read the header and could not find it");
HERO_STR_STATIC(hero_str_4984a51, "an `extern` names what the header already has (\302\2474.19): check the spelling, or name the header that does declare `");
HERO_STR_STATIC(hero_str_2d81771, "the header declares `");
HERO_STR_STATIC(hero_str_70ce66e, "did you mean");
HERO_STR_STATIC(hero_str_1fc2f816, "did you mean '");
HERO_STR_STATIC(hero_str_74547321, "clang offered no correction");
HERO_STR_STATIC(hero_str_1ef0dbf6, "missing field '");
HERO_STR_STATIC(hero_str_44788dd6, "not a missing-field line");
HERO_STR_STATIC(hero_str_5def2f2c, "no position on the line");
HERO_STR_STATIC(hero_str_50f6728b, "no group record sits on that line");
HERO_STR_STATIC(hero_str_2d35ebc5, "ffi_incomplete_record");
HERO_STR_STATIC(hero_str_7a6d9d44, "` does not name `");
HERO_STR_STATIC(hero_str_7cb31b7e, "`, and `");
HERO_STR_STATIC(hero_str_1984bf76, "` says the struct has it \342\200\224 a group's `record` IS the header's struct, so a field left out is a field C fills with zero");
HERO_STR_STATIC(hero_str_2a09c51c, "the assertions above check every field you DO name and cannot see one you leave out: a `");
HERO_STR_STATIC(hero_str_475dee3d, "` built here would carry a zero `");
HERO_STR_STATIC(hero_str_37cde76e, "` into C, which is a value rather than a crash");
HERO_STR_STATIC(hero_str_4023d265, ": error:");
HERO_STR_STATIC(hero_str_620945a7, "not an error line");
HERO_STR_STATIC(hero_str_1a8045c0, "no row and column before the message");
HERO_STR_STATIC(hero_str_34c52e1b, "the row is not a number");
HERO_STR_STATIC(hero_str_e47121d, "no group record on that line");
HERO_STR_STATIC(hero_str_2fc59cb, "not a union assertion");
HERO_STR_STATIC(hero_str_37c890c, "no group declares this record");
HERO_STR_STATIC(hero_str_51ed8b8f, "ffi_union_field");
HERO_STR_STATIC(hero_str_7bdff571, "its member");
HERO_STR_STATIC(hero_str_44bb528b, "` is a `union` in `");
HERO_STR_STATIC(hero_str_36a2000b, "`, so comparing or hashing one asks about bytes that may hold another member \342\200\224 `");
HERO_STR_STATIC(hero_str_7c9f8527, "` is only what was written last");
HERO_STR_STATIC(hero_str_52742f8e, "reading `");
HERO_STR_STATIC(hero_str_5aed825d, "` and building one that names it are both sound and stay legal; what has no answer is `==`, `hash` and being a map key, because two values holding different members are equal whenever the bytes match. Mark the `record` `partial` if you want that refusal stated at the declaration");
HERO_STR_STATIC(hero_str_5a5fb126, "`, so ");
HERO_STR_STATIC(hero_str_7d071c43, " are the same bytes \342\200\224 building one or comparing it would answer about whichever was written last");
HERO_STR_STATIC(hero_str_34312024, "a `record` over a union may name ONE member, and that binds it soundly: reading through it is correct and construction sets the member it names. Two or more is what has no answer \342\200\224 C keeps the last one written, so `==` and `hash` walk the same bytes twice");
HERO_STR_STATIC(hero_str_12f14992, "no group record has this name");
HERO_STR_STATIC(hero_str_12a2f262, "not a field assertion");
HERO_STR_STATIC(hero_str_261b4bc9, "no group record has this field");
HERO_STR_STATIC(hero_str_3dcd0cc2, "` \342\200\224 clang read the header's struct and the field disagrees");
